<?php
require_once __DIR__.'/includes/db.php';$pdo=db();$coach=(int)($_GET['coach']??0);$day=(string)($_GET['day']??'');$where=[];$args=[];if($coach){$where[]='s.coach_id=?';$args[]=$coach;}if($day!==''&&in_array($day,['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'],true)){$where[]='s.weekday=?';$args[]=$day;}$sql='SELECT s.*,c.name coach FROM schedules s LEFT JOIN coaches c ON c.id=s.coach_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY CASE s.weekday WHEN "Понедельник" THEN 1 WHEN "Вторник" THEN 2 WHEN "Среда" THEN 3 WHEN "Четверг" THEN 4 WHEN "Пятница" THEN 5 WHEN "Суббота" THEN 6 ELSE 7 END,s.time';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$coaches=$pdo->query('SELECT id,name FROM coaches ORDER BY name')->fetchAll();$pageTitle='Расписание тренировок';require __DIR__.'/includes/header.php';
?><section class="mx-auto max-w-7xl px-4 py-14"><p class="font-bold uppercase tracking-widest text-red-500">Планируй тренировку</p><h1 class="mt-2 text-4xl font-black">Расписание занятий</h1><form class="panel my-8 flex flex-col gap-4 rounded-2xl p-5 sm:flex-row sm:items-end"><label class="flex-1 text-sm text-gray-300">Тренер<select name="coach" class="mt-2 w-full rounded-lg border border-white/10 bg-neutral-900 p-3 text-white"><option value="0">Все тренеры</option><?php foreach($coaches as $c):?><option value="<?=$c['id']?>" <?=$coach===(int)$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label class="flex-1 text-sm text-gray-300">День недели<select name="day" class="mt-2 w-full rounded-lg border border-white/10 bg-neutral-900 p-3 text-white"><option value="">Все дни</option><?php foreach(['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'] as $d):?><option <?=($day===$d?'selected':'')?>><?=h($d)?></option><?php endforeach;?></select></label><button class="rounded-lg bg-sport px-6 py-3 font-bold">Показать</button><a class="rounded-lg border border-white/20 px-6 py-3 text-center" href="schedule.php">Сбросить</a></form><div class="grid gap-4 md:grid-cols-2 lg:grid-cols-3"><?php foreach($rows as $r):?><article class="panel rounded-2xl border border-white/5 p-6"><div class="schedule-heading flex items-start justify-between gap-4"><span class="rounded-lg bg-red-950 px-3 py-2 font-bold text-red-300"><?=h($r['weekday'])?></span><span class="text-lg font-black"><?=h($r['time'])?></span></div><h2 class="mt-5 text-xl font-bold"><?=h($r['discipline'])?></h2><p class="mt-2 text-sm text-gray-400">Группа <?=h($r['group_name'])?></p><p class="mt-2 text-sm text-gray-300"><i class="fa-solid fa-user-tie mr-2 text-red-500"></i><?=h($r['coach']??'Тренер не указан')?></p><p class="mt-2 text-sm text-gray-400"><i class="fa-solid fa-location-dot mr-2"></i><?=h($r['venue'])?></p></article><?php endforeach;?><?php if(!$rows):?><p class="text-gray-400">Занятий по выбранным параметрам нет.</p><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';
